insert into "monthly_asset_performance" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body") values ('2026-05-01', 'ภาพรวมผลตอบแทนสินทรัพย์ — เดือนแห่งการฟื้นตัวของหุ้นเทคโนโลยีและตลาดเกิดใหม่', '2026-05-01', 'ภาพรวมผลตอบแทนสินทรัพย์ — เดือนแห่งการฟื้นตัวของหุ้นเทคโนโลยีและตลาดเกิดใหม่', 'บทวิเคราะห์ผลตอบแทนสินทรัพย์รายเดือน พฤษภาคม 2569', '2026-05-01', '2026-05-01', '2026-05-31', '{"url": "https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/20260505_Yuanta_Monthly_Asset_Allocation_May_2026/component_images/page_11.png?v=20260617", "altText": "", "type": "image"}'::jsonb, 'เมื่อ Big Tech ทำ All-Time High และ KOSPI พุ่ง 30% — โลกการลงทุนเปลี่ยนไปแล้วในเดือนเมษายน', '<p><span>ตลาดหุ้นโลกพุ่งขึ้น 10.03% ในเดือนเมษายน 2569 นำโดยกลุ่มเซมิคอนดักเตอร์และ Big Tech หลังผลประกอบการ 1Q26 แข็งแกร่งกว่าคาด ขณะที่ Fed คงดอกเบี้ยและส่งสัญญาณ Hawkish กดดันทองคำ</span></p><p><span>นักลงทุนควรเพิ่มน้ำหนักหุ้นกลุ่ม Technology และ Communication ขณะที่ลด Defensive และทองคำในพอร์ตระยะสั้น</span></p>', '<h3><span>ภาพรวมผลตอบแทนสินทรัพย์</span></h3>
<p><span>ในเดือนเมษายน 2569 ตลาดสินทรัพย์ทั่วโลกปรับตัวขึ้นอย่างแข็งแกร่งท่ามกลางบรรยากาศ risk-on ที่ครอบงำตลาดตลอดทั้งเดือน โดยได้แรงหนุนหลักจากผลประกอบการไตรมาส 1 ปี 2026 ของกลุ่มเทคโนโลยีและเซมิคอนดักเตอร์ที่ออกมาดีกว่าที่นักวิเคราะห์คาดการณ์ไว้ รวมถึงการหยุดยิงระหว่างสหรัฐฯ กับอิหร่านในช่วงต้นเดือนที่ช่วยลดความตึงเครียดด้านภูมิรัฐศาสตร์</span></p>
<p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/20260505_Yuanta_Monthly_Asset_Allocation_May_2026/component_images/page_11.png?v=20260617'' width=''1282'' height=''890'' loading=''lazy'' alt=''Asset Classes Performance YTD and April 2026'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>
<p><span>ภาพรวมของสินทรัพย์หลักในเดือนเมษายน 2569 มีดังนี้ Global Equities ปรับตัวขึ้น +10.03% (YTD +6.16%) และ Global Equities ex-US ขึ้น +9.34% (YTD +7.99%) สะท้อนการฟื้นตัวที่กว้างขวางทั้งในและนอกสหรัฐฯ ด้าน USD Index อ่อนค่าลง -1.76% (YTD -0.19%) ซึ่งเป็นปัจจัยหนุนสินทรัพย์นอกสหรัฐฯ ขณะที่ US Oil ปรับขึ้น +3.64% แม้จะยังต่ำกว่าระดับสูงสุดในปีนี้ที่ +96.71% และทองคำ (Gold) ร่วงลง -1.01% แม้ YTD ยังเป็นบวกที่ +6.95% ด้านอัตราผลตอบแทนพันธบัตรสหรัฐฯ ปรับขึ้นทั้งเส้น โดย 10Y UST อยู่ที่ 4.37% (ช่วง 1 ปี: 3.95%–4.60%) ส่วน 30Y อยู่ที่ 4.97% (ช่วง: 4.54%–5.09%)</span></p>

<p>&nbsp;</p>
<h3><span>สินทรัพย์ที่โดดเด่น</span></h3>
<ul>
  <li><span>ผู้นำตลาดหุ้นโลก — KOSPI (เกาหลีใต้) +30.61% ในเดือนเมษายน (YTD +56.59%) หนุนโดยการฟื้นตัวของกลุ่มเซมิคอนดักเตอร์และผลประกอบการที่แข็งแกร่งกว่าคาด</span></li>
  <li><span>รองลงมา — TWSE (ไต้หวัน) +22.71% ในเดือนเมษายน (YTD +34.40%) และ Nikkei 225 (ญี่ปุ่น) +16.10% (YTD +17.77%) ทั้งสองดัชนีได้ประโยชน์จากกระแสการลงทุนในห่วงโซ่อุปทานเซมิคอนดักเตอร์</span></li>
  <li><span>หุ้นสหรัฐฯ — S&P 500 ปรับตัวขึ้น +10.42% ทำ All-Time High เป็นครั้งที่ 11 ของปีนี้ ถือเป็นผลตอบแทนรายเดือนที่ดีที่สุดนับตั้งแต่ปี 2020 ขณะที่ Nasdaq ทำได้ดีกว่าที่ +15.29%</span></li>
  <li><span>สินทรัพย์ที่อ่อนแอที่สุด — SET Index (ไทย) -1.30% ในเดือนเมษายน (YTD -8.16%) สะท้อนแรงฟื้นตัวเศรษฐกิจในประเทศที่ยังเปราะบาง และภาพเงินเฟ้อต่ำที่ยังไม่เอื้อต่อการขยายตัวของกำไรบริษัท</span></li>
  <li><span>ทองคำ (Gold) ร่วง -1.01% ในเดือนเมษายน แม้ปกติจะได้ประโยชน์จากความไม่แน่นอน แต่ถูกกดดันจาก 10Y UST Yield ที่ปรับขึ้นสู่ระดับ 4.37%</span></li>
</ul>
<p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/20260505_Yuanta_Monthly_Asset_Allocation_May_2026/component_images/page_12.png?v=20260617'' width=''1282'' height=''890'' loading=''lazy'' alt=''Global Stock Market Performance by Region'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>

<p>&nbsp;</p>
<h3><span>ผลตอบแทนรายกลุ่มอุตสาหกรรมในตลาดหุ้นสหรัฐฯ</span></h3>
<p><span>กลุ่ม Growth นำตลาดสหรัฐฯ อย่างชัดเจนในเดือนเมษายน 2569 โดย Communication Services ปรับขึ้นสูงสุดที่ +18.43% (YTD +10.03%) และ Technology ตาม +17.44% (YTD +6.57%) หนุนโดยผลประกอบการ 1Q26 ของกลุ่ม Big Tech และเซมิคอนดักเตอร์ที่แข็งแกร่งกว่าคาด พร้อมแนวโน้มกำไรที่เป็นบวกต่อเนื่องในช่วงที่เหลือของปี ด้าน Real Estate ปรับขึ้น +8.65% และ Industrial +7.90% (YTD +12.57%) ขณะที่ Energy เป็นกลุ่มที่อ่อนแอที่สุดในเดือนนี้ที่ -3.51% แม้ YTD ยังนำตลาดที่ +32.43% ส่วนกลุ่ม Defensive อย่าง Healthcare -0.58% (YTD -5.83%) และ Consumer Staples +2.95% ค่อนข้าง underperform สะท้อนบรรยากาศที่นักลงทุนหันมารับความเสี่ยงมากขึ้น</span></p>
<p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/20260505_Yuanta_Monthly_Asset_Allocation_May_2026/component_images/page_13.png?v=20260617'' width=''1282'' height=''890'' loading=''lazy'' alt=''US Sector Performance YTD and April 2026'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>

<p>&nbsp;</p>
<h3><span>ปัจจัยขับเคลื่อนผลตอบแทน</span></h3>
<p><span>ปัจจัยหลักที่ขับเคลื่อนผลตอบแทนในเดือนเมษายน 2569 มาจากหลายทิศทางพร้อมกัน ประการแรก การหยุดยิงระหว่างสหรัฐฯ กับอิหร่านในช่วงต้นเดือนลดแรงกดดันด้านภูมิรัฐศาสตร์และหนุนให้ตลาดกลับมา risk-on ประการที่สอง ผลประกอบการ 1Q26 ของกลุ่มเทคโนโลยีและเซมิคอนดักเตอร์ที่ออกมาแข็งแกร่งกว่าคาด พร้อมการปรับเพิ่มประมาณการกำไรสำหรับช่วงที่เหลือของปีและปี 2027 เป็นแรงหนุนสำคัญสำหรับ KOSPI, TWSE, Nikkei และ Nasdaq ประการที่สาม แม้บรรยากาศการลงทุนจะดี แต่ด้านมหภาคมีสัญญาณที่ต้องติดตาม กล่าวคือ GDP QoQ ของสหรัฐฯ ชะลอจาก 1.4% เหลือ 0.5% (Signal: Warning) และ Citi Global Economic Surprise ลดจาก 23.2 เหลือ 8.3 (Signal: Warning) บ่งชี้ว่า momentum ทางเศรษฐกิจที่แท้จริงเริ่มอ่อนแรงลง ราคาพลังงานที่ยังอยู่ในระดับสูงหลัง Strait of Hormuz ยังคงปิดอยู่ หนุนให้เงินเฟ้อสหรัฐฯ เร่งตัวขึ้นสู่ 3.60% ใน 2Q26e จาก 3.00% ใน 1Q26 ส่งผลให้ Fed คงดอกเบี้ยที่ 3.73% และส่งสัญญาณ Hawkish กดดันทองคำและพันธบัตร ขณะที่ ECB ส่งสัญญาณอาจขึ้นดอกเบี้ยในเดือนมิถุนายนจากแรงกดดันเงินเฟ้อพลังงาน</span></p>

<p>&nbsp;</p>
<h3><span>ภาพเศรษฐกิจโลกและ Regime Map</span></h3>
<p><span>Regime Map ของ Yuanta CIO ณ สิ้นเดือนเมษายน 2569 สะท้อนภาพเศรษฐกิจโลกที่แยกตัวออกเป็นหลาย Regime ชัดเจนขึ้น โดยสหรัฐฯ เคลื่อนจากโซน Reflation เข้าสู่บริเวณใกล้ Stagflation เนื่องจาก GDP ที่คาดว่าจะชะลอจาก 2.70% ใน 1Q26 เหลือ 2.20% ใน 2Q26e ขณะที่เงินเฟ้อเร่งตัวขึ้น ด้านยุโรปและญี่ปุ่นยังอยู่ใกล้โซนเงินเฟ้อสูง ส่วนจีนและไทยยังอยู่ฝั่ง growth ต่ำ-เงินเฟ้อต่ำ ใกล้ Hard Landing โดยจีน GDP คาดที่ 4.60% และเงินเฟ้อเพิ่งเริ่มฟื้นสู่ 1.10% ใน 2Q26e จากภาวะลบในปีก่อน ขณะที่ไทย GDP คาดที่ 1.20% ใน 2Q26e และเงินเฟ้อเพิ่งกลับเป็นบวกที่ 0.40% สะท้อนว่าแรงฟื้นตัวในเอเชียยังต้องอาศัยนโยบายกระตุ้น</span></p>
<p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/20260505_Yuanta_Monthly_Asset_Allocation_May_2026/page_images/page_009.png?v=20260617'' width=''1282'' height=''890'' loading=''lazy'' alt=''Global Economic Regime Map and Data Table'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>

<p>&nbsp;</p>
<h3><span>ความเสี่ยงและโอกาสการลงทุน</span></h3>
<ul>
  <li><span>หุ้นกลุ่ม Technology และ Communication Services ใน S&P 500 และ Nasdaq ยังคงมีแรงส่งจากผลประกอบการที่แข็งแกร่งและ Guidance เชิงบวกต่อเนื่อง เหมาะสำหรับการถือครองในพอร์ต core equity</span></li>
  <li><span>KOSPI และ TWSE มี upside จากกระแสเซมิคอนดักเตอร์ที่ยังแข็งแกร่ง แต่ความผันผวนสูง ควรพิจารณาในฐานะ satellite allocation สำหรับนักลงทุนที่รับความเสี่ยงได้สูง</span></li>
  <li><span>US 10Y Treasury Yield ที่ระดับ 4.37% ใกล้บริเวณกลางของ 1-year range (3.95%–4.60%) เปิดโอกาสสะสม IG Bond อย่างระมัดระวัง โดย Spread IG ที่ 0.80 ลดลงจาก 0.93 บ่งชี้ credit quality ยังดี</span></li>
  <li><span>ทองคำ (Gold) ถูกกดดันจาก Real Yield ที่สูงขึ้น แนะนำลดสัดส่วนในระยะสั้นและรอจังหวะสะสมคืนหากเศรษฐกิจสหรัฐฯ ชะลอตัวแรงกว่าคาดในช่วง 2Q–3Q26</span></li>
  <li><span>SET Index และสินทรัพย์ไทยยัง underperform อย่างมีนัยสำคัญ (YTD -8.16%) ควรรอสัญญาณฟื้นตัวของ GDP ในประเทศก่อนเพิ่มน้ำหนัก โดยติดตามนโยบายกระตุ้นการคลังและทิศทางอัตราดอกเบี้ยของ BOT ที่คาดว่าจะปรับลดลงสู่ 0.94% ใน 2Q26e</span></li>
  <li><span>ความเสี่ยงหลักที่ต้องจับตาคือ GDP QoQ ของสหรัฐฯ ที่ชะลอสู่ 0.5% และ Citi Global Economic Surprise ที่ลดลงสู่ 8.3 (Warning) หากตัวเลขเศรษฐกิจอ่อนแอต่อเนื่อง ควรเตรียม defensive hedge ผ่าน HY Bond Spread monitoring และ VIX Index ที่ยังอยู่ระดับ 18.21</span></li>
</ul>');
insert into "monthly_asset_performance" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body") values ('2026-06-01', 'ภาพรวมผลตอบแทนสินทรัพย์ — เดือนแห่งการนำของเทคโนโลยีและการปรับตัวของตลาดเอเชีย', '2026-06-01', 'ภาพรวมผลตอบแทนสินทรัพย์ — เดือนแห่งการนำของเทคโนโลยีและการปรับตัวของตลาดเอเชีย', 'บทวิเคราะห์ผลตอบแทนสินทรัพย์รายเดือน มิถุนายน 2569', '2026-06-01', '2026-06-01', '2026-06-30', NULL, 'เมื่อน้ำมันดิ่งและชิปพุ่ง ตลาดโลกเดือนพฤษภาคมบอกอะไรเราเกี่ยวกับโอกาสและความเสี่ยงที่กำลังจะมาถึง', '<p><span>เดือนพฤษภาคม 2569 Global Equities ปรับขึ้น +4.98% นำโดยกลุ่ม Technology +15.91% จากธีม Agentic AI และ CPU compute ขณะที่ US Oil ดิ่ง -16.86% ตามความคืบหน้าการเจรจา US-Iran</span></p><p><span>นักลงทุนควรเฝ้าระวังสัญญาณ Yuanta Strength Composite Score ที่พุ่งขึ้นสู่ 93% จาก Sentiment เป็นหลัก ซึ่งอาจไม่ยั่งยืน และควรลดการไล่ราคาในระดับปัจจุบัน</span></p>', '<h3><span>ภาพรวมผลตอบแทนสินทรัพย์</span></h3><p><span>ในเดือนพฤษภาคม 2569 ภาพรวมสินทรัพย์ทั่วโลกดำเนินอยู่ในบรรยากาศ risk-on ต่อเนื่อง โดย Global Equities ปรับขึ้น +4.98% ในเดือนพฤษภาคม และให้ผลตอบแทน YTD ที่ +11.45% ขณะที่ US Oil เป็นสินทรัพย์ที่ปรับตัวลงแรงที่สุดที่ -16.86% ในเดือนเดียวกัน</span></p><p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/Yuanta_Monthly_Asset_Allocation_June_2026/component_images/page_11.png'' width=''1282'' height=''890'' loading=''lazy'' alt=''Asset Classes and US Bond Yield Performance'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p><p><span>ในภาพรวมสินทรัพย์หลัก ตราสารทุนโลกเป็นผู้นำที่ชัดเจน ขณะที่สินค้าโภคภัณฑ์ปรับตัวลง -4% และทองคำลดลง -1.69% ในเดือนพฤษภาคม (YTD +5.14% โดยมีจุดสูงสุดปีนี้ที่ +25.31%) สะท้อนบรรยากาศ risk-on ที่ลดความต้องการสินทรัพย์ปลอดภัย ด้าน Dollar Index กลับมาแข็งค่า +1% ขณะที่ US Bond Yield ปรับขึ้นทั้ง curve โดย 2Y +13.5 bps มาอยู่ที่ 4.00%, 10Y +6.3 bps มาอยู่ที่ 4.44% และ 30Y +0.8 bps มาอยู่ที่ 4.97%</span></p><p>&nbsp;</p><h3><span>สินทรัพย์ที่โดดเด่น</span></h3><ul><li><span>ผู้นำตลาด — KOSPI +28.45% ในเดือนพฤษภาคม (YTD +101.13%) นำตลาดหุ้นโลกทิ้งห่างอย่างมีนัยสำคัญ</span></li><li><span>Taiwan Weighted (TWSE) +14.92% ในเดือนพฤษภาคม (YTD +54.45%) สะท้อนแรงหนุนจาก supply chain เซมิคอนดักเตอร์</span></li><li><span>Nikkei 225 +11.88% ในเดือนพฤษภาคม (YTD +16.08%) outperform ตลาดเอเชียเหนือต่อเนื่อง</span></li><li><span>Nasdaq Composite +8.36% ในเดือนพฤษภาคม (YTD +16.05%) และ S&P 500 +5.15% ปิดเหนือ 7,500 จุด ทำ all-time high ครั้งที่ 22 ในปีนี้</span></li><li><span>SET Index ปรับตัวลง -11.92% ในเดือนพฤษภาคม (YTD -1.9%) เป็นตลาดที่ underperform มากที่สุดในกลุ่ม</span></li><li><span>Hang Seng CEI -2.95% ในเดือนพฤษภาคม (YTD -5.47%) สะท้อนตัวเลขเศรษฐกิจและผลประกอบการที่ยังไม่ฟื้นตัวชัดเจน</span></li><li><span>US Oil เป็นสินทรัพย์ที่ปรับลงแรงที่สุดที่ -16.86% ในเดือนพฤษภาคม (YTD -1.95% โดยมีจุดสูงสุดปีนี้ที่ +96.71%)</span></li></ul><p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/Yuanta_Monthly_Asset_Allocation_June_2026/component_images/page_12.png'' width=''1282'' height=''890'' loading=''lazy'' alt=''Global Stock Market Index Performance'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p><p>&nbsp;</p><h3><span>ภาพรวม US Sector และปัจจัยขับเคลื่อน</span></h3><p><span>US Sector เดือนพฤษภาคมสะท้อนการกระจุกตัวของแรงซื้อในกลุ่ม Technology อย่างชัดเจน โดย Technology ปรับตัวขึ้น +15.91% (YTD +23.54%) นำตลาดแบบทิ้งห่าง sector อื่น ปัจจัยหลักมาจากผลประกอบการ 1Q26 ของกลุ่ม CPU ทั้ง AMD, NVIDIA และ ARM ที่ปรับมุมมองต่อ Server CPU TAM ขึ้นแรง จากดีมานด์ Agentic AI และ Inference workload ที่ต้องการ CPU compute เพิ่มขึ้นอย่างมีนัยสำคัญ ซึ่งส่งผลบวกต่อ supply chain ทั้งสาย ตั้งแต่ Foundry ไปจนถึงกลุ่ม Memory ที่ได้ประโยชน์จากความต้องการ HBM, DDR5 และ NAND รวมถึงกระแสเงินทุนไหลกลับเข้าหุ้นกลุ่ม Software</span></p><p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/Yuanta_Monthly_Asset_Allocation_June_2026/component_images/page_13.png'' width=''1282'' height=''890'' loading=''lazy'' alt=''US Sector Performance by Category May 2026'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p><p><span>ในขณะที่กลุ่ม Defensive และ Cyclical ส่วนใหญ่ปรับตัวลง โดยเฉพาะ Energy -6.08% (YTD +24.38%) ที่ถูกกดดันจากราคาน้ำมันที่ดิ่งลงตามความคืบหน้าการเจรจา US-Iran และ Utility -5.52% (YTD +3.67%) ด้าน Consumer Staples ลดลง -3.29% ส่วนกลุ่ม Cyclical อย่าง Financial -1.18%, Industrial -0.97% และ Materials -0.85% ปรับตัวลงเล็กน้อย ในขณะที่ Consumer Discretionary +2.56% (YTD +3.86%) และ Healthcare +2.31% (YTD -3.66%) ยังเป็นบวกได้</span></p><p>&nbsp;</p><h3><span>สัญญาณเศรษฐกิจมหภาคและ Regime Map</span></h3><p><span>ภาพเศรษฐกิจโลกเริ่มแตกแยกเป็นหลาย regime มากขึ้น โดยสหรัฐฯ เข้าใกล้ภาวะ Stagflation มากขึ้น จากการที่ US Inflation เร่งตัวขึ้นสู่ระดับ 3.90% ในประมาณการ 2Q26e ขณะที่ GDP ชะลอลงจาก 2.70% ใน 1Q26e มาอยู่ที่ 2.30% ใน 2Q26e ยุโรปมี Growth ชะลอและเงินเฟ้อยังคงอยู่ในระดับสูง ขณะที่ญี่ปุ่นเงินเฟ้อไม่เร่งตัวตามที่กังวล สอดคล้องกับ Growth ที่ชะลอตัว ส่วนไทยและจีนเผชิญโจทย์โตช้าและเงินเฟ้อเริ่มขึ้นตัว โดยไทยมีประมาณการเงินเฟ้อ 2Q26e ที่ 3.10% พุ่งขึ้นจาก -0.50% ใน 1Q26e</span></p><p><img src=''https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/Yuanta_Monthly_Asset_Allocation_June_2026/page_images/page_009.png'' width=''1282'' height=''890'' loading=''lazy'' alt=''GDP Inflation Policy Rate Forecast Table'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p><p>&nbsp;</p><h3><span>สัญญาณ Risk Monitoring และ Composite Score</span></h3><p><span>Yuanta Strength Composite Score (YSCS) ปรับขึ้นแรงจาก 65% (ณ 25 เมษายน 2569) มาอยู่ที่ 93% (ณ 25 พฤษภาคม 2569) โดยมีปัจจัยหลักมาจากกลุ่ม Financial Indicator ที่ดีขึ้น ได้แก่ VIX ลดลงมาอยู่ที่ 17.00 (จาก 18.21), Spread HY คลายตัวมาที่ 2.74 (จาก 2.86), Spread IG ที่ 0.74 (จาก 0.80) และ BB US Financial Condition ที่ 1.018 (จาก 0.935) ในขณะที่ US Recession Probability (12M) ลดลงมาอยู่ที่ 25% (-5% จากเดือนก่อน) อย่างไรก็ดี Citi Global Econ Surprise อยู่ที่ 12.30 (จาก 8.3) ถูกจัดอยู่ในระดับ Warning และ Nonfarm Payrolls ลดลงมาอยู่ที่ 115 (จาก 185) ซึ่งอยู่ในระดับ Neutral</span></p><p><span>Yuanta CIO ระบุว่า YSCS ที่สูงระดับนี้มาจาก Sentiment เป็นหลัก และอาจไม่ได้ยั่งยืนหรือยืนสูงเป็นเวลานาน ดังนั้นระดับปัจจุบันควรอยู่ในโหมดเฝ้าระวังมากกว่าการไล่ลงทุน โดยยังไม่อยู่ในเกณฑ์อันตรายระดับ recession alarm</span></p><p>&nbsp;</p><h3><span>ความเสี่ยงและโอกาสการลงทุน</span></h3><ul><li><span>กลุ่ม Technology และ Semiconductor supply chain (AMD, NVIDIA, ARM รวมถึง Memory กลุ่ม HBM/DDR5/NAND) ยังเป็นธีมหลักที่ได้รับแรงหนุนจาก Agentic AI และ CPU compute demand แต่ราคาที่ปรับขึ้นมามากแล้วควรพิจารณาความเสี่ยงด้าน Valuation</span></li><li><span>ตลาดหุ้นเอเชียเหนือ โดยเฉพาะ KOSPI (+28.45% MTD, +101.13% YTD) และ TWSE (+14.92% MTD, +54.45% YTD) ยังคง outperform สะท้อนประโยชน์จาก supply chain ชิปและ AI</span></li><li><span>US Bond Yield ที่ปรับขึ้นทั้ง curve (2Y ที่ 4.00%, 10Y ที่ 4.44%, 30Y ที่ 4.97%) สะท้อนเงินเฟ้อที่เร่งตัวและแนวโน้ม Fed ที่อาจ delay การลดดอกเบี้ย นักลงทุนควรระวังความเสี่ยง Duration ในพอร์ตตราสารหนี้</span></li><li><span>ทองคำ (Gold) ปรับลง -1.69% ในเดือนพฤษภาคม แม้ YTD ยังบวก +5.14% โดยมีจุดสูงสุดปีนี้ที่ +25.31% แรงกดดันจาก Yield ที่สูงขึ้นและบรรยากาศ risk-on เป็นปัจจัยกดดันในระยะสั้น</span></li><li><span>Energy Sector ปรับลง -6.08% ในเดือนพฤษภาคม แม้ YTD ยังบวก +24.38% ความเสี่ยงจากราคา US Oil ที่ดิ่งลง -16.86% MTD ควรพิจารณาทบทวนน้ำหนักการลงทุนในกลุ่มนี้</span></li><li><span>SET Index ที่ปรับลง -11.92% ในเดือนพฤษภาคม ประกอบกับไทยเผชิญประมาณการเงินเฟ้อที่พุ่งขึ้นแรงสู่ 3.10%–4.20% ใน 2Q26e–4Q26e และ GDP ที่ชะลอ นักลงทุนควรติดตามการส่งผ่านราคาพลังงานในไทยอย่างใกล้ชิด</span></li></ul>');
insert into "monthly_asset_performance" ("path", "hs_name", "week_slug", "main_title", "page_subtitle", "page_date", "week_start_date", "week_end_date", "cover_image", "description", "ai_summary", "body") values ('2026-07-01', 'ภาพรวมผลตอบแทนสินทรัพย์ — มิถุนายน 2569 เดือนแห่ง Rotation และการคลาย Geopolitical Premium', '2026-07-01', 'ภาพรวมผลตอบแทนสินทรัพย์กรกฎาคม 2569 เดือนแห่ง Rotation และการคลาย Geopolitical Premium', 'บทวิเคราะห์ผลตอบแทนสินทรัพย์รายเดือน กรกฎาคม 2569', '2026-07-01', '2026-07-01', '2026-07-31', '{"url": "https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/2026-07-01/images/page_12.png", "altText": "", "type": "image"}'::jsonb, 'เมื่อสงครามยุติ ทองคำดิ่ง น้ำมันร่วง — แต่หุ้นยุโรปและ Value กลับเปล่งประกาย เดือนมิถุนายนพิสูจน์ว่าตลาดการเงินไม่เคยหยุดนิ่ง', '<p><span>ในเดือนมิถุนายน 2569 การยุติสงคราม US-Iran ฉุด US Oil ดิ่ง 20.44% และทองคำร่วง 11.79% ขณะที่ตลาดหุ้นเกิด rotation ชัดเจนจาก Growth สู่ Cyclical และ Defensive โดย Industrial นำสูงสุด +7.19% ในขณะที่ Comm Services ปรับลงแรงสุด -7.85%</span></p>', '<h3><span>ภาพรวมผลตอบแทนสินทรัพย์</span></h3>
<p><span>ในเดือนมิถุนายน 2569 ภาพรวมสินทรัพย์ทั่วโลกถูกกำหนดทิศทางโดยการยุติสงครามระหว่างสหรัฐฯ กับอิหร่าน ซึ่งเปิดทางให้ Strait of Hormuz กลับมาเดินเรือได้ตามปกติ ส่งผลให้ราคา US Oil ดิ่งลงถึง 20.44% กลับสู่ระดับก่อนสงคราม และเป็นตัวกดดันหลักต่อกลุ่ม Commodity ที่ปรับลง 8.83% ขณะที่ Gold ร่วงแรง 11.79% จากการคลาย geopolitical premium ที่สะสมมาตลอดช่วงสงคราม ด้าน Global Equities พักตัวเล็กน้อย 0.91% หลังปรับขึ้นแรงต่อเนื่องในช่วงก่อนหน้า</span></p>
<p><span>Dollar Index แข็งค่าต่อเนื่อง 2.25% ขึ้นทำ new high เพิ่มแรงกดดันต่อสินทรัพย์ที่อิงดอลลาร์อย่างทองคำ ขณะที่ US Bond Yield ปรับขึ้น นำโดย 2Y +16.8 bps มาอยู่ที่ 4.17% สะท้อนการที่ตลาดเริ่มมองว่า Fed อาจกลับมาขึ้นดอกเบี้ย หลังตัวเลข Nonfarm Payrolls ออกมาแข็งแกร่ง ประกอบกับ FOMC ส่งสัญญาณเปิดทางขึ้นดอกเบี้ย ส่วน 10Y ปรับขึ้น +2.4 bps มาอยู่ที่ 4.46% และ 30Y ปรับลง -2.3 bps มาอยู่ที่ 4.95%</span></p>

<p><img src="https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/monthly-reports/2026-07-01/images/page_11.png" width=''1282'' height=''890'' loading=''lazy'' alt=''Asset Classes and US Bond Yield Performance'' style=''height: auto; max-width: 100%; width: 1282px; margin-left: auto; margin-right: auto; display: block;''></p>
<p style=''text-align: center;''><span style=''font-size: 12px; color: #6b7280;''>รูป: Asset Classes and US Bond Yield Performance</span></p>

<p>&nbsp;</p><h3><span>สินทรัพย์ที่โดดเด่น — ภาพรวม Asset Classes</span></h3>
<ul>
  <li><span>US Oil: -20.44% ในเดือนมิถุนายน (YTD: 21.04%) — ปรับลงจากการที่ Strait of Hormuz กลับมาเปิดให้เดินเรือหลังสงคราม US-Iran ยุติ; ระดับสูงสุด YTD อยู่ที่ 96.71%</span></li>
  <li><span>Gold: -11.79% ในเดือนมิถุนายน (YTD: -7.26%) — ปรับลงจากการคลาย geopolitical premium; ระดับต่ำสุด YTD อยู่ที่ -7.47%</span></li>
  <li><span>Commodity: -8.83% ในเดือนมิถุนายน — ถูกฉุดโดยราคาน้ำมันที่ดิ่งลงแรง</span></li>
  <li><span>USD Index: +2.25% ในเดือนมิถุนายน — แข็งค่าต่อเนื่องขึ้นทำ new high</span></li>
  <li><span>Global Equities: -0.91% ในเดือนมิถุนายน — พักตัวเล็กน้อยหลังปรับขึ้นแรงต่อเนื่องในช่วงก่อนหน้า</span></li>
</ul>

<p>&nbsp;</p><h3><span>ผลตอบแทนตลาดหุ้นรายภูมิภาค</span></h3>
<p><span>ตลาดหุ้นทั่วโลกในเดือนมิถุนายน 2569 เข้าสู่ภาวะ rotation อย่างชัดเจน โดยกลุ่ม Technology และ Semiconductor ที่เคยนำตลาดเริ่มพักฐาน เม็ดเงินหมุนเข้าสู่กลุ่ม value, หุ้นขนาดเล็ก และตลาดนอกสหรัฐฯ ทำให้ leadership ของตลาดกระจายตัวมากขึ้น</span></p>

